  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "The highest-similarity analogue showed good rat brain penetration with Kpuu,brain 0.47 and Kpuu,CSF 0.76, indicating that this quinazoline/quinoline-type inhibitor scaffold can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "AZD3759, a CNS-penetrant EGFR TKI with a similar bicyclic aminoaryl core, achieved Kp,uu,brain 1.3 in preclinical models, supporting transfer of good BBB penetration to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In humans, AZD3759 showed approximately 1:1 CSF-to-plasma concentrations, providing direct human evidence that this chemotype penetrates the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Vorasidenib, which shares the CF3-bearing aminoheteroaryl motif, had a brain tumor-to-plasma concentration ratio of 1.69 in a phase I study, demonstrating CNS penetration for a structurally related molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lapatinib is a less-similar quinazoline analogue with very low brain-to-plasma ratios (0.013-0.028) due to efflux; its large polar sulfonamide tail and transporter liabilities are not present in the query, so this contradictory evidence is outweighed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the preponderance of transferable in vivo evidence from structurally related CNS-penetrant kinase inhibitors (Kpuu,brain 0.34-1.3, human CSF:plasma ~1, brain tumor:plasma 1.69) supports meaningful CNS access for the query. The main negative analogue, lapatinib, is less similar and its poor brain penetration is driven by efflux and a polar sulfonamide tail not present in the query.",
  "evidence_gaps": [
    "No direct experimental CNS exposure data for the exact query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.22), limiting structural transfer.",
    "The pyridine N-oxide moiety is not represented in the evidence set; its effect on passive permeability and efflux is uncertain.",
    "No P-gp/BCRP efflux data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

